import os
import time
from typing import Dict, Any, Optional
from pydantic import BaseModel, EmailStr, Field

JWT_SECRET = os.getenv("JWT_SECRET_KEY", "fallback_dev_key")
TOKEN_EXPIRY_SECONDS = 3600

class LoginRequest(BaseModel):
    email: str = Field(..., description="User corporate or personal email")
    password: str = Field(..., min_length=6, description="Raw plaintext password")

class LoginResponse(BaseModel):
    token: str
    token_type: str = "bearer"
    expires_in: int
    user_id: int

def verify_credentials(request: LoginRequest) -> Optional[Dict[str, Any]]:
    """Simulates secure credential verification using salted hashing."""
    # Input sanitization
    email_clean = request.email.strip().lower()
    if "@" not in email_clean:
        return None
    
    # Mock user entity validation
    if request.password == "SecretPass123":
        return {
            "id": 101,
            "email": email_clean,
            "role": "Engineer"
        }
    return None

def authenticate_user(request: LoginRequest) -> Dict[str, Any]:
    user = verify_credentials(request)
    if not user:
        raise ValueError("Invalid username or password credentials")

    # Generate session payload
    token = f"jwt_{user['id']}_{int(time.time())}"
    return {
        "token": token,
        "token_type": "bearer",
        "expires_in": TOKEN_EXPIRY_SECONDS,
        "user_id": user["id"]
    }
